"""Family-independent HAL headers (the API every driver is written against)."""

HDR = """/**
 * @file    {name}
 * @brief   {brief}
 *
 * Generated by ChipLlama (deterministic, no AI) for {device}.
 */
#ifndef {guard}
#define {guard}

{body}
#endif /* {guard} */
"""


def header(name, brief, body, device):
    guard = name.upper().replace(".", "_").replace("/", "_") + "_"
    return HDR.format(name=name, brief=brief, body=body.strip() + "\n", guard=guard, device=device)


def src(name, brief, body, device):
    return (f"/**\n * @file    {name}\n * @brief   {brief}\n *\n * Generated by ChipLlama (deterministic, no AI) for {device}.\n */\n"
            + body.strip() + "\n")


HAL_H = """
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/** @brief Status code returned by every HAL and driver function that can fail. */
typedef enum
{{
    HAL_OK              =  0,   /**< success */
    HAL_ERR_PARAM       = -1,   /**< invalid argument */
    HAL_ERR_TIMEOUT     = -2,   /**< peripheral did not respond in time */
    HAL_ERR_NACK        = -3,   /**< I2C slave did not acknowledge */
    HAL_ERR_UNSUPPORTED = -4,   /**< not generated for this device family */
    HAL_ERR_BUSY        = -5,   /**< no data available / peripheral busy */
    HAL_ERR_DEVICE      = -6    /**< device answered with an unexpected ID / CRC */
}} hal_status_t;

/** @brief Native SFR width of this device family. */
typedef {reg_t} hal_reg_t;

/** @brief Instruction-cycle frequency in Hz (Fcy). */
#define HAL_FCY_HZ          ({fcy}UL)
"""

GPIO_H = """
#include "hal.h"

/** @brief One GPIO pin: its TRIS / LAT / PORT registers and bit mask. */
typedef struct
{
    volatile hal_reg_t       *tris;  /**< direction register (1 = input) */
    volatile hal_reg_t       *lat;   /**< output latch */
    volatile const hal_reg_t *port;  /**< pin level */
    hal_reg_t                 mask;  /**< bit mask of the pin */
} hal_gpio_t;

/** @brief Drive an output pin. @param pin pin descriptor @param level true = high */
void hal_gpio_write(const hal_gpio_t *pin, bool level);
/** @brief Read the pin level. @return true when the pin is high */
bool hal_gpio_read(const hal_gpio_t *pin);
/** @brief Invert an output pin. */
void hal_gpio_toggle(const hal_gpio_t *pin);
/** @brief Set direction. @param output true = output */
void hal_gpio_set_output(const hal_gpio_t *pin, bool output);
"""

GPIO_C = """
#include "hal_gpio.h"

void hal_gpio_write(const hal_gpio_t *pin, bool level)
{
    if (pin != NULL)
    {
        if (level) { *pin->lat |= pin->mask; }
        else       { *pin->lat &= (hal_reg_t)~pin->mask; }
    }
}

bool hal_gpio_read(const hal_gpio_t *pin)
{
    return (pin != NULL) && ((*pin->port & pin->mask) != 0U);
}

void hal_gpio_toggle(const hal_gpio_t *pin)
{
    if (pin != NULL)
    {
        *pin->lat ^= pin->mask;
    }
}

void hal_gpio_set_output(const hal_gpio_t *pin, bool output)
{
    if (pin != NULL)
    {
        if (output) { *pin->tris &= (hal_reg_t)~pin->mask; }
        else        { *pin->tris |= pin->mask; }
    }
}
"""

